<?php
require_once 'auth.php';require_admin();require_once 'material-utils.php';$pdo=db();$id=(int)($_POST['id']??0);$materialId=(int)($_POST['material_id']??0);$files=$_FILES['images']??null;
if(!$pdo||!$materialId||!$files){header('Location: materials.php?error=Yêu cầu không hợp lệ');exit;}
try{$added=0;foreach((array)$files['tmp_name'] as $i=>$tmp){$file=['name'=>$files['name'][$i]??'','tmp_name'=>$tmp,'error'=>$files['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$files['size'][$i]??0];if($file['error']===UPLOAD_ERR_NO_FILE)continue;if($file['error']!==UPLOAD_ERR_OK)continue;$code=filename_code($file['name']);$hex=average_hex($file['tmp_name']);$image=material_upload($file,'materials/colors');if(!$image)continue;if($id){$pdo->prepare('UPDATE material_colors SET code=?,image=?,hex_code=? WHERE id=? AND material_id=?')->execute([$code,$image,$hex,$id,$materialId]);$added=1;break;}$pdo->prepare('INSERT INTO material_colors(material_id,code,image,hex_code) VALUES(?,?,?,?)')->execute([$materialId,$code,$image,$hex]);$added++;}if(!$added)throw new RuntimeException('Không có ảnh hợp lệ');header('Location: material-form.php?id='.$materialId.'&ok='.urlencode($id?'Đã lưu màu':'Đã thêm '.$added.' màu'));}catch(Throwable $e){header('Location: material-color-form.php?material_id='.$materialId.'&error='.urlencode('Không thể xử lý ảnh').($id?'&id='.$id:''));}
